import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'

export function middleware(request: NextRequest) {
  // Log the request pathname to the console
  console.log(`Request pathname: ${request.nextUrl.pathname}`)

  // Generate a unique request ID
  const requestId = crypto.randomUUID()

  // Create the response
  const response = NextResponse.next()

  // Add the custom header
  response.headers.set('X-Request-Id', requestId)

  return response
}

export const config = {
  matcher: [
    /*
     * Match all request paths except for the ones starting with:
     * - _next/static (static files)
     * - _next/image (image optimization files)
     * - favicon.ico (favicon file)
     */
    '/((?!_next/static|_next/image|favicon.ico).*)',
  ],
}

import { defineConfig } from 'vitest/config'
import react from '@vitejs/plugin-react'

export default defineConfig({
  plugins: [react()],
  test: {
    environment: 'node',
  },
})

import { describe, it, expect, vi } from 'vitest'
import { middleware } from './middleware'
import { NextRequest } from 'next/server'

describe('Middleware', () => {
  it('adds X-Request-Id header and logs pathname', () => {
    // Mock console.log
    const logSpy = vi.spyOn(console, 'log').mockImplementation(() => {})

    // Create a request
    const request = new NextRequest(new URL('http://localhost:3000/test-path'))

    // Call the middleware
    const response = middleware(request)

    // Check header
    const requestId = response.headers.get('X-Request-Id')
    expect(requestId).toBeTruthy()
    // UUID length check
    expect(requestId?.length).toBe(36)

    // Check log
    expect(logSpy).toHaveBeenCalledWith('Request pathname: /test-path')

    logSpy.mockRestore()
  })
})
